class _MDropout(nn.Module):
    def __init__(self, rate):
        super().__init__()
        self.dropout = nn.Dropout(rate)
        self.rate = rate
    def forward(self, x):
        if self.training:
            x = self.dropout(x)            
        else:
            x = x

        return x



class Block60(nn.Module):
    '''
    Last cvv 
    '''

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp = MLP(config)
        self.router = nn.Linear(config.n_embd,3,bias=True)

    def forward(self, x):
        # att = self.router(x).softmax(-1   )
        att = self.router(self.ln_1(x)).softmax(-1)
        
        x2=  self.attn(self.ln_1(x))
        x3 = self.mlp(self.ln_2(x))
        # print((att*100).mean((0,1)).double())
        x = torch.einsum('btk,kbte->bte',att,torch.stack([x,x2,x3],dim=0))
        
        ## tensor([23.8678, 28.6459, 47.4863], device='cuda:0', dtype=torch.float64)

        return x



