class Block68(nn.Module):
    '''
    same as gpt but dynamically set the mixing probability
    '''

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention67(config)

        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp   = MLP(config)


    def forward(self, x,x2,x3):
        dx1,eng1 = self.attn(self.ln_1(x), self.ln_1(x))
        dx2,eng2 = self.attn(self.ln_1(x), self.ln_1(x2))
        dx3,eng3 = self.attn(self.ln_1(x), self.ln_1(x3))
        dx = torch.einsum('btk,kbte->bte', torch.stack([eng1,eng2,eng3],-1).softmax(-1), torch.stack([dx1,dx2,dx3],0) )
        x = x + dx
        # x = dx

        # x = (x + self.mlp(self.ln_2(x)))

        return x



