class MLP325(nn.Module):
    

    def __init__(self, config):
        super().__init__()
        self.c_fc     = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_proj  = nn.Linear(4 * config.n_embd, config.n_embd, bias=config.bias)
        self.dropout = nn.Dropout(config.dropout)

        self.nk = nk = 3
        # print(nk)
        self.lora_1a     = nn.Linear(nk,config.n_embd,bias=False)
        self.lora_1b     = nn.Linear(nk,4*config.n_embd,bias=False)

        self.lora_2a     = nn.Linear(nk,4*config.n_embd,bias=False)
        self.lora_2b     = nn.Linear(nk,config.n_embd,bias=False)

    def forward(self, x, dx2):
        
        dx2k = dx2[:,0,:self.nk]
        x0 = x

        # self.lora_1a(dx2k)
        x1 = 0.
        wt = self.c_fc.weight.T
        x1 = x1 + x0.matmul(wt)
        x1 = x1 + x0 @ torch.einsum('bv,ve,vf->bef', dx2k, self.lora_1a.weight.T, self.lora_1b.weight.T)
        xx = (x1).sigmoid()

        x = 0
        dx2k = dx2[:,0,self.nk:self.nk*2]
        wt = self.c_proj.weight.T
        x2 = (xx*x1)        
        x = x + x2.matmul(wt)
        x = x + x2 @ torch.einsum('bv,ve,vf->bef', dx2k, self.lora_2a.weight.T, self.lora_2b.weight.T)

        x = self.dropout(x)
        return x


class Block325(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention323(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLP325(config)

    def forward(self, x, x0, dx1, dx2):
        dx = self.attn(self.ln_1(x),self.ln_1(x0),dx1)
        x = x + dx
        dx = self.mlp(self.ln_2(x),dx2)
        x = x + dx
        return x




class CausalSelfAttention323(nn.Module):

    def __init__(self, config):
        super().__init__()
        assert config.n_embd % config.n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(config.n_embd, 3 * config.n_embd, bias=config.bias)
        # output projection
        self.c_proj = nn.Linear(config.n_embd, config.n_embd, bias=config.bias)
        # regularization

        # self.dropout = nn.Dropout(config.dropout)
        # _dclass = _Dropout42B
        _dclass = nn.Dropout

        self.attn_dropout  = _dclass(config.dropout)
        self.resid_dropout = _dclass(config.dropout)
        
        self.n_head = config.n_head
        self.n_embd = config.n_embd
        self.dropout = config.dropout
        # flash attention make GPU go brrrrr but support is only in PyTorch >= 2.0
        self.flash = hasattr(torch.nn.functional, 'scaled_dot_product_attention')
        # self.flash = False
        if not self.flash:
            print("WARNING: using slow attention. Flash Attention requires PyTorch >= 2.0")
            # causal mask to ensure that attention is only applied to the left in the input sequence
            self.register_buffer("bias", torch.tril(torch.ones(config.block_size, config.block_size))
                                        .view(1, 1, config.block_size, config.block_size))

    def forward(self, x, x0, dx1):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, _, _  = self.c_attn(x).split(self.n_embd, dim=2)
        _, k, v  = self.c_attn(x0).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        if self.flash:
            # efficient attention using Flash Attention CUDA kernels
            y = torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask=None, dropout_p=self.dropout if self.training else 0, is_causal=True)
        else:
            # manual implementation of attention
            att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
            att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))

            # att  = att.transpose(1,2)
            att = att.sigmoid()
            # att = F.softmax(att, dim=-1)
            att = self.attn_dropout(att)
            
            y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y




# class GPT325(GPT):
class GPT325(GPT323):
    '''
    same as 172 but ablating the attention module
    same as 141D but with a symbolic layer at the end, mixing rank-1 linear map.
    same as 141 but adding vector norm regularisation at the end
    same as 140 but using static displacement vector in MLP 
    same as 131 but using fully replaced MLP, and linear MLP activation and maps
    same as 117 but trying to use a local representation instead of a global one
    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token


    '''



    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            h = nn.ModuleList([Block325(config) for _ in range(config.n_layer) ] ),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True





class Block326(nn.Module):

    def __init__(self, config):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention326(config)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        self.mlp  = MLP326(config)

    def forward(self, x, x0, dx1, dx2):
        dx = self.attn(self.ln_1(x),self.ln_1(x0),dx1)
        x = x + dx
        dx = self.mlp(self.ln_2(x),dx2)
        x = x + dx
        return x


class LoraLinear(nn.Module):
    def __init__(self, dim_in, dim_out, lora_dim, bias=True, proj=False):
        super().__init__()
        self.dim_in  = dim_in
        self.dim_out = dim_out
        self.baselin      = nn.Linear(dim_in, dim_out, bias=bias)
        self.lora_in      = nn.Linear( lora_dim, dim_in,bias=False)
        self.lora_out     = nn.Linear( lora_dim, dim_out,bias=False)
        
        self.lora_proj   = nn.Linear(lora_dim, lora_dim, bias=False)        
        self.proj =proj
        # self.lora2   = nn.Linear(nk, nk, bias=config.bias)       
        # self.lora_bias = nn.Linear()

    def forward(self, x, vlora):        
        '''
        vlora of shape (B,V)
        '''
        x1 = 0.
        # wt = self.baselin.weight.T
        x1 = x1 + self.baselin(x)
        if self.proj:
            vlora = self.lora_proj(vlora)
        x1 = x1 + x @ torch.einsum('bv,ve,vf->bef', vlora, self.lora_in.weight.T, self.lora_out.weight.T)
        return x1



class MLP326(nn.Module):
    
    def __init__(self, config):
        super().__init__()
        self.nk          = nk  = 3
        self.c_fc     = LoraLinear(config.n_embd, 4 * config.n_embd, nk, bias=config.bias)
        self.c_proj   = LoraLinear(4 * config.n_embd, config.n_embd, nk, bias=config.bias)        
        self.dropout = nn.Dropout(config.dropout)

    def forward(self, x, dx2):
        
        x1 = self.c_fc(x, dx2)
        x  = self.c_proj(x1.sigmoid()*x1, dx2)        
        x  = self.dropout(x)
        return x
 




class CausalSelfAttention326(nn.Module):

    def __init__(self, config):
        super().__init__()
        assert config.n_embd % config.n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(config.n_embd, 3 * config.n_embd, bias=config.bias)
        # output projection
        self.c_proj = nn.Linear(config.n_embd, config.n_embd, bias=config.bias)
        # regularization

        _dclass = nn.Dropout

        self.attn_dropout  = _dclass(config.dropout)
        self.resid_dropout = _dclass(config.dropout)
        
        self.n_head = config.n_head
        self.n_embd = config.n_embd
        self.dropout = config.dropout
        # flash attention make GPU go brrrrr but support is only in PyTorch >= 2.0
        self.flash = hasattr(torch.nn.functional, 'scaled_dot_product_attention')
        # self.flash = False
        if not self.flash:
            print("WARNING: using slow attention. Flash Attention requires PyTorch >= 2.0")
            # causal mask to ensure that attention is only applied to the left in the input sequence
            self.register_buffer("bias", torch.tril(torch.ones(config.block_size, config.block_size))
                                        .view(1, 1, config.block_size, config.block_size))

    def forward(self, x, x0, dx1):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, _, _  = self.c_attn(x).split(self.n_embd, dim=2)
        _, k, v  = self.c_attn(x0).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        if self.flash:
            # efficient attention using Flash Attention CUDA kernels
            y = torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask=None, dropout_p=self.dropout if self.training else 0, is_causal=True)
        else:
            # manual implementation of attention
            att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
            att = att.masked_fill(self.bias[:,:,:T,:T] == 0, float('-inf'))

            # att  = att.transpose(1,2)
            att = att.sigmoid()
            # att = F.softmax(att, dim=-1)
            att = self.attn_dropout(att)
            
            y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
        y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

        # output projection
        y = self.resid_dropout(self.c_proj(y))
        return y





class GPT326(GPT323):
    '''
    same as 172 but ablating the attention module
    same as 141D but with a symbolic layer at the end, mixing rank-1 linear map.
    same as 141 but adding vector norm regularisation at the end
    same as 140 but using static displacement vector in MLP 
    same as 131 but using fully replaced MLP, and linear MLP activation and maps
    same as 117 but trying to use a local representation instead of a global one
    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token


    '''



    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config
        config.nk = 10

        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(config.vocab_size, config.n_embd),
            wpe = nn.Embedding(config.block_size, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            h = nn.ModuleList([Block326(config) for _ in range(config.n_layer) ] ),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, config.vocab_size, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True




    def forward(self, idx, targets=None):
        if self.reset and not self.training:
            # print([self.norm_m.item(),self.norm_w.item(),self.norm_b.item()])
            print([self.norm_w.exp().item()])
            self.reset = False
        if self.training:
            self.reset = True
        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"
        pos = torch.arange(0, t, dtype=torch.long, device=device) # shape (t)

        # forward the GPT model itself
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb

        # ns = 10
        ns = 3
        x = x[None].repeat((ns,1,1,1)).reshape((-1,x.shape[1],x.shape[2]))
        x0 = x
        targetss = targets[None].repeat((ns,1,1,1)).view(ns*b,t)
        xtarg = self.transformer.wte(targetss)

        dx1 = torch.tensor( 0.1* (torch.rand_like(x)[None].repeat(self.config.n_layer,1,1,1)-0.5), requires_grad=True)
        dx2 = torch.tensor( 0.1* (torch.rand_like(x)[None].repeat(self.config.n_layer,1,1,1)-0.5), requires_grad=True)
        if self.training:
            pass

        else:
            dx1 = torch.zeros_like(dx1,requires_grad=True)
            dx2 = torch.zeros_like(dx2,requires_grad=True)


        # dx1 = torch.tensor( 0.1* (torch.zeros_like(x)[None].repeat(self.config.n_layer,1,1,1)), requires_grad=True)
        # dx2 = torch.tensor( 0.1* (torch.zeros_like(x)[None].repeat(self.config.n_layer,1,1,1)), requires_grad=True)

        # dx = torch.zeros_like(x, requires_grad=True)
        ## pre process the token to 
        nk = 3
        def ar(x,dx1,dx2):
            # x = x0
            for i,block in enumerate(self.transformer.h):
                x = block( x, x, dx1[i], dx2[0][:,0,:nk])
            x = self.transformer.ln_f(x)
            return x

        # if self.training:
        if 1:
            # print('[startgd]') 
            # smax = 5
            smax = 3
            # smax = 6
            # smax = 0
            for stepi in range(smax):
                y = ar(x.detach(),dx1,dx2)
                # lp = - 0.01 * (y - xtarg).square()

                ###(bte)
                logits = self.lm_head(y)
                loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                lp = -loss.mean()
                
                # lp = torch.einsum('bte,bte->bt',y,xtarg)
                # lp  = lp.sum(-1)
                lp = lp.mean()
                # print(lp.item())                
                if stepi==smax-1:
                    break

                # lp.requires_grad = True
                lp.backward(inputs=[dx2],retain_graph=True)
                # lp.backward(retain_graph=False)
                # alpha = 2.
                alpha = 5.
                # alpha = 0.1

                with torch.no_grad():
                    # dx.data = dx.data + alpha * dx.grad.data        
                    # dx1 = dx1 + alpha * dx1.grad
                    # dx2 = dx2 + alpha * dx2.grad
                    dx2 = dx2 + alpha * dx2.grad.clip(-0.05,0.05)
                    # dx2 = dx2 + alpha * dx2.grad.clip(-0.005,0.005)
                    # dx2 = dx2 + alpha * dx2.grad.clip(-0.000,0.000)
                    # dx = dx.clip(-0.2,0.2)
                dx1.requires_grad = True
                dx2.requires_grad = True
            # dx2 = dx2.clip(self.low, self.high)

        y = ar(x,dx1,dx2)


        if targets is not None:
            # logits = (x*w)
            logits = self.lm_head(y)
            # *self.norm_w.exp())    
            ###(bte)
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
            loss = loss.mean()
            # if self.training:
            #     loss = loss + dx2.square().mean()
        return logits, loss       







