        # dx1,eng1 = self.attn(self.ln_1(x), self.ln_1(x))
        dx1,eng1 = self.attn(self.ln_1(x), (x))
        # x = dx1
        x = x +dx1
        # x = dx
        # x = (x + self.mlp(self.ln_2(x)))

        return x



