class CausalSelfAttention547(nn.Module):

    def __init__(self, config, is_causal=True,bias=None):
        super().__init__()
        if bias is None:
            bias = config.bias
        assert config.n_embd % config.n_head == 0
        # key, query, value projections for all heads, but in a batch
        self.c_attn = nn.Linear(config.n_embd, 3 * config.n_embd, bias=bias)
        # output projection
        self.c_proj = nn.Linear(config.n_embd, config.n_embd, bias=bias)
        # regularization

        # self.dropout = nn.Dropout(config.dropout)
        # _dclass = _Dropout42B
        _dclass = nn.Dropout

        self.attn_dropout  = _dclass(config.dropout)
        self.resid_dropout = _dclass(config.dropout)
        
        self.n_head = config.n_head
        self.n_embd = config.n_embd
        self.dropout = config.dropout
        # flash attention make GPU go brrrrr but support is only in PyTorch >= 2.0
        self.flash = hasattr(torch.nn.functional, 'scaled_dot_product_attention')
        self.flash = False
        self.is_causal = is_causal
        self.config = config
        if not self.flash:
            print("WARNING: using slow attention. Flash Attention requires PyTorch >= 2.0")
            # causal mask to ensure that attention is only applied to the left in the input sequence
            pass
            # self.register_buffer("bias", torch.tril(torch.ones(config.block_size+config.nm*2, config.block_size+config.nm*2))
            #                             .view(1, 1, config.block_size+config.nm*2, config.block_size+config.nm*2))

    def forward(self, x, x0,is_copy=False):
        B, T, C = x.size() # batch size, sequence length, embedding dimensionality (n_embd)

        # calculate query, key, values for all heads in batch and move head forward to be the batch dim
        q, k, _  = self.c_attn(x).split(self.n_embd, dim=2)
        _, _, v  = self.c_attn(x0).split(self.n_embd, dim=2)
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2) # (B, nh, T, hs)

        # causal self-attention; Self-attend: (B, nh, T, hs) x (B, nh, hs, T) -> (B, nh, T, T)
        is_causal = self.is_causal
        if self.flash:
            assert 0
            # efficient attention using Flash Attention CUDA kernels
            y = torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask=None, dropout_p=self.dropout if self.training else 0, is_causal=is_causal)
        else:
            config = self. config
            bias = torch.tril(torch.ones(config.block_size*3, config.block_size*3,device=x.device)
                                        .view(1, 1, config.block_size*3, config.block_size*3))
            # manual implementation of attention
            att = (q @ k.transpose(-2, -1)) * (1.0 / math.sqrt(k.size(-1)))
            if is_causal:
                att = att.masked_fill(bias[:,:,:T,:T] == 0, float('-inf'))


            # att = F.softmax(att, dim=-1)
            
            if is_copy:
                att = att.sigmoid()
                att = self.attn_dropout(att)
                # print(att.sum(1).shape,x0.shape,(B,T,C))
                # y = att.sum(1)@ x0
                y = att[:,0]@ x0
                # [:,None].repeat(1,self.n_head,1,1))
            else:

                att = att.sigmoid()
                att = self.attn_dropout(att)

                y = att @ v # (B, nh, T, T) x (B, nh, T, hs) -> (B, nh, T, hs)
                y = y.transpose(1, 2).contiguous().view(B, T, C) # re-assemble all head outputs side by side

                # output projection
                y = self.resid_dropout(self.c_proj(y))
            # print(y.shape)
        return y

class GPT235(GPT):
    '''
    same as 231 but adding a latent context graph to be used
    same as 174 but using a importance sampling gradient estimator
    same as 172 but ablating the attention module
    same as 141D but with a symbolic layer at the end, mixing rank-1 linear map.
    same as 141 but adding vector norm regularisation at the end
    same as 140 but using static displacement vector in MLP 
    same as 131 but using fully replaced MLP, and linear MLP activation and maps
    same as 117 but trying to use a local representation instead of a global one
    Kernellising the MLP activation function s(k) to be rank 1 bilinear kernels
    same as GPT102G but introducing a gaussian approximation of bernoulli variables
    Preprocessed token
    '''

    def __init__(self, config):
        super(GPT,self).__init__()

        assert config.vocab_size is not None
        assert config.block_size is not None
        self.config = config

        vmax = config.vocab_size+500+10
        # nm = 10
        self.vmax = vmax
        config.nm = nm = 10
        self.transformer = nn.ModuleDict(dict(
            wte = nn.Embedding(vmax, config.n_embd),
            wme = nn.Embedding(500, config.n_embd),
            wpe = nn.Embedding(config.block_size+nm*2, config.n_embd),
            drop = nn.Dropout(config.dropout),
            
            # h0 = nn.ModuleList([Block140(config) for _ in range(1)]),
            h0 = nn.ModuleList([Block235(config) for _ in range(config.n_layer)]),
            # h1 = nn.ModuleList([Block117(config) for _ in range(config.n_layer-1)] +  [Block130(config) for _ in range(1)]),
            h1 = nn.ModuleList([Block235(config) for _ in range(config.n_layer)] ),
            hp = nn.ModuleList([Block235(config) for _ in range(config.n_layer)] ),
            # hlast = Block231(config),
            ln_f = LayerNorm(config.n_embd, bias=config.bias),
        ))
        self.lm_head = nn.Linear(config.n_embd, vmax, bias=False)
        # self.lm_norm = nn.Linear(1, config.vocab_size, bias=True)
        # self.lm_null = nn.Linear(1, config.vocab_size, bias=False)
        # self.norm_m = nn.Parameter(torch.tensor(7.5))
        ### precision of the gaussian distrib
        self.norm_w = nn.Parameter(torch.tensor(0.))
        # self.norm_b = nn.Parameter(torch.tensor(0.))

        # with weight tying when using torch.compile() some warnings get generated:
        # "UserWarning: functional_call was passed multiple values for tied weights.
        # This behavior is deprecated and will be an error in future versions"
        # not 100% sure what this is, so far seems to be harmless. TODO investigate
        self.transformer.wte.weight = self.lm_head.weight # https://paperswithcode.com/method/weight-tying

        # init all weights
        self.apply(self._init_weights)
        # apply special scaled init to the residual projections, per GPT-2 paper
        for pn, p in self.named_parameters():
            if pn.endswith('c_proj.weight'):
                torch.nn.init.normal_(p, mean=0.0, std=0.02/math.sqrt(2 * config.n_layer))

        # report number of parameters
        print("number of parameters: %.2fM" % (self.get_num_params()/1e6,))
        self.reset = True

        # self.prior_logsigma = nn.Parameter(torch.tensor(math.log(0.1),device=x.device))
        # self.post_logsigma = nn.Parameter(torch.tensor(math.log(0.1),device=x.device))

        self.prior_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))
        self.post_logsigma = nn.Parameter(torch.tensor(math.log(0.1)))


    def forward(self, idx, targets=None):
        if self.reset and not self.training:
            # print([self.norm_m.item(),self.norm_w.item(),self.norm_b.item()])
            print([self.norm_w.exp().item(), self.prior_logsigma.exp().item(), self.post_logsigma.exp().item()])
            self.reset = False
        if self.training:
            self.reset = True
        device = idx.device
        b, t = idx.size()
        assert t <= self.config.block_size, f"Cannot forward sequence of length {t}, block size is only {self.config.block_size}"

        ns = 6
        nm = 10

        idx = idx.repeat((ns,1,1)).reshape((ns*b,t))
        # t = t + nm
        pos = torch.arange(0, t+nm, dtype=torch.long, device=device) + nm # shape (t)

        # forward the GPT model itself
        idx1 = torch.cat([idx, torch.ones_like(idx[:,:nm]).long()*(self.vmax-1)],dim=1)

        tok_emb = self.transformer.wte(idx1) # token embeddings of shape (b, t, n_embd)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        x = tok_emb + pos_emb


        # ns = 10
        # ns = 6
        # x = x[None].repeat((ns,1,1,1)).reshape((-1,x.shape[1],x.shape[2]))

        x0 = x


        ### calculate the last memory context vectors
        x = x0
        for block in self.transformer.h1:
            x = block(x,x)
        x1 = x
        xz = x[:,-nm:]

        
        prior_logsigma = self.prior_logsigma
        post_logsigma  = self.post_logsigma

        post_invsqsigma = 1./(2*post_logsigma).exp()

        xz_noise = xz + torch.normal(0.,1.,xz.shape,device=xz.device) * post_logsigma.exp()

        invsqsigma = 1./(2*prior_logsigma).exp()
        lpz  = -0.5*invsqsigma * (xz_noise-0.).square() - prior_logsigma - 0.5*math.log(2 * math.pi)
        lpz = lpz.sum(-1)
        lpq  = -0.5*post_invsqsigma * (xz_noise-xz).square() - post_logsigma - 0.5*math.log(2 * math.pi)
        lpq = lpq.sum(-1)


        

        ### concating the ending segment to the left of decoder
        pos = torch.arange(0, t+nm, dtype=torch.long, device=device) + 0 # shape (t)
        pos_emb = self.transformer.wpe(pos) # position embeddings of shape (t, n_embd)
        tok_emb = self.transformer.wte(idx) # token embeddings of shape (b, t, n_embd)
        tok_emb = torch.cat([xz_noise, tok_emb],dim=1)
        # lprior = 

        x = tok_emb + pos_emb
        for block in self.transformer.h0:
            x = block(x,x)
        # print(x[:,nm:].std())

        x = x[:,nm:]

        x = self.transformer.ln_f(x)



        if targets is not None:

            logits = self.lm_head(x)
            loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
            lpy = -loss.reshape((ns,b,t)).sum(-1)
            lpz = lpz.reshape(ns,b,-1).sum(-1)
            lpq = lpq.reshape(ns,b,-1).sum(-1)

            if not self.training:

                loss = lpy + lpz - lpq
                # lpz = lpz.view((ns,b,t))

                ### logmeanexp
                # mpy = lpy.logsumexp(0) - math.log(ns)                

                loss = -loss.mean() / t

            else:
                ### estimating gradient from the p(y|z)p(z|x)
                ### lpy lpz
                # logits = self.lm_head(x)
                # loss = F.cross_entropy(logits.view(-1, logits.size(-1)), targets[None].repeat((ns,1,1,1)).reshape(-1), ignore_index=-1,reduction='none')
                # lpy = -loss.reshape((ns,b,t))
                # lpz = lpz.view((ns,b,t))

                ### estimating local log partiaion function \sum_z p(y|z) p(z|x)

                ### 1. old estimation
                # lpy  = lpy.sum(2)
                ### logmeanexp
                # cxy  = lpy.logsumexp(0) - math.log(ns)
                # loss = (lpy - cxy).exp().detach() * (lpy + lpz.sum(2)) 
                # loss = loss * ns / t

                elbo = lpy + lpz - lpq
                loss = elbo + (elbo-elbo.mean(0,keepdims=True)).detach()*lpq
                
                loss = -loss.mean() / t


                # ### 2. combined into a softmax
                # lpy  = lpy.sum(2)
                # # loss = lpy.softmax(0).detach()* (lpy + lpz.sum(2)) 
                # lpyp = lpy.softmax(0)
                # ### removing baseline from second term
                # # loss = lpyp.detach()* lpy + (lpyp - lpyp.mean(0,keepdims=True)).detach()* lpz.sum(2)
                # ### actually there is no need to calculate, because softmax always sum to 1

                # # loss = lpyp.detach()* lpy + (lpyp - 1./ns).detach()* lpz.sum(2)
                # # loss = lpyp.detach()* (lpy + lpz.sum(2))
                # loss = lpyp.detach()* (lpy) 
                # loss = loss * ns/ t
                
                # #### estimator for mean-field elbo
                # # (lpy-lpy.logsumexp(0,keepdims=True)+math.log(ns)).exp().detach() * lpz
                
                # loss = -loss.mean()
                # pass
            

        return logits, loss       



