class Block554(nn.Module):

    def __init__(self, config, is_causal=True,is_attn=1, bias=None):
        super().__init__()
        self.ln_1 = LayerNorm(config.n_embd, bias=config.bias)
        self.attn = CausalSelfAttention547(config, is_causal, bias)
        self.ln_2 = LayerNorm(config.n_embd, bias=config.bias)
        # self.mlp  = MLP171(config)

        self.c_fc     = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_fc2    = nn.Linear(config.n_embd, 4 * config.n_embd, bias=config.bias)
        self.c_proj2  = nn.Linear(4 * config.n_embd, config.n_embd, bias=False)
        self.dropout = nn.Dropout(config.dropout)
        self.is_attn=is_attn


    def forward(self, x, x0, attn_x = None, mlp_x= None):
        # ctx = self.attn(self.ln_1(x),self.ln_1(x0),)
        # x = self.attn(self.ln_1(x),self.ln_1(x0),)
        ctx = x
        # x = dx
        if mlp_x is None:
            mlp_x = x
        att = self.c_fc(self.ln_2(mlp_x)).sigmoid()

        dx_mlp = self.dropout(self.c_proj2(self.c_fc2(x)*att))
        xo = 0.
        v_attn = 0
        if self.is_attn:
            if attn_x is None:
                attn_x = x
            v_attn = self.attn(self.ln_1(attn_x),self.ln_1(x0),)
        xo = x + dx_mlp  + v_attn
        # xo = x + (self.c_proj2(self.c_fc2(x2)*att))  + self.attn(self.ln_1(x),self.ln_1(x0),)
        return xo

